package com.careerguidance.controller; import com.careerguidance.dto.request.AssessmentFeedbackRequest; import com.careerguidance.dto.response.*; import com.careerguidance.service.MentorReviewService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/mentor/students/{id}/assessment") public class AssessmentReviewController {private final MentorReviewService service;public AssessmentReviewController(MentorReviewService s){service=s;} @GetMapping @org.springframework.security.access.prepost.PreAuthorize("hasRole('MENTOR')") public AssessmentReviewResponse get(Authentication a,@PathVariable Long id){return service.assessment(a,id);}@PostMapping("-feedback") @org.springframework.security.access.prepost.PreAuthorize("hasRole('MENTOR')") public MessageResponse feedback(Authentication a,@PathVariable Long id,@Valid @RequestBody AssessmentFeedbackRequest r){service.assessmentFeedback(a,id,r);return new MessageResponse("Assessment feedback submitted");}}
